struct DrawableSize { int width = 0; int height = 0; };
DrawableSize platform_drawable_size();
void platform_present();

DrawableSize platform_drawable_size()
{
    if (!active || active->should_close ||
        (SDL_GetWindowFlags(active->window.get()) & SDL_WINDOW_MINIMIZED)) return {};
    DrawableSize size;
    SDL_GL_GetDrawableSize(active->window.get(), &size.width, &size.height);
    return size;
}

gl.UseProgram(program);
gl.BindVertexArray(vao);
gl.Viewport(0, 0, width, height);
gl.ClearColor(0.05f, 0.08f, 0.12f, 1.0f);
gl.Clear(ColorBufferBit);
gl.DrawArrays(Triangles, 0, 3);
gl.BindVertexArray(0);
gl.UseProgram(0);

void platform_present()
{
    const auto size = platform_drawable_size();
    if (size.width > 0 && size.height > 0) SDL_GL_SwapWindow(active->window.get());
}

const auto size = platform_drawable_size();
if (size.width > 0 && size.height > 0) {
    if (!study_gl::draw_triangle(gl, program.name(), vertex_array.name(),
                                 size.width, size.height)) return 1;
    platform_present();
}
platform_end_frame();

std::array<unsigned char, 4> rgba{};
gl.ReadPixels(64, 60, 1, 1, RGBA, UnsignedByte, rgba.data());
if (gl.GetError() != 0) return false;
